{
  "items": [
    {
      "name": "Fintype.mem_piFinset",
      "type": " {α : Type u_1} [DecidableEq α] [Fintype α] {δ : α → Type u_4} {t : (a : α) → Finset (δ a)} {f : (a : α) → δ a} : f ∈ Fintype.piFinset t ↔ ∀ (a : α), f a ∈ t a",
      "module": "Mathlib.Data.Fintype.Pi"
    },
    {
      "name": "Fin.snoc_mem_piFinset_snoc",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {x_last : α (Fin.last n)} {x_init : (i : Fin n) → α i.castSucc} {s_last : Finset (α (Fin.last n))} {s_init : (i : Fin n) → Finset (α i.castSucc)} : Fin.snoc x_init x_last ∈ Fintype.piFinset (Fin.snoc s_init s_last) ↔ x_last ∈ s_last ∧ x_init ∈ Fintype.piFinset s_init",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    },
    {
      "name": "Fin.mem_piFinset_iff_last_init",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {f : (i : Fin (n + 1)) → α i} {s : (i : Fin (n + 1)) → Finset (α i)} : f ∈ Fintype.piFinset s ↔ f (Fin.last n) ∈ s (Fin.last n) ∧ Fin.init f ∈ Fintype.piFinset (Fin.init s)",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    },
    {
      "name": "Fin.insertNth_mem_piFinset_insertNth",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {p : Fin (n + 1)} {x_pivot : α p} {x_remove : (i : Fin n) → α (p.succAbove i)} {s_pivot : Finset (α p)} {s_remove : (i : Fin n) → Finset (α (p.succAbove i))} : p.insertNth x_pivot x_remove ∈ Fintype.piFinset (p.insertNth s_pivot s_remove) ↔ x_pivot ∈ s_pivot ∧ x_remove ∈ Fintype.piFinset s_remove",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    },
    {
      "name": "Fin.mem_piFinset_iff_pivot_removeNth",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {f : (i : Fin (n + 1)) → α i} {s : (i : Fin (n + 1)) → Finset (α i)} (p : Fin (n + 1)) : f ∈ Fintype.piFinset s ↔ f p ∈ s p ∧ p.removeNth f ∈ Fintype.piFinset (p.removeNth s)",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    },
    {
      "name": "Fin.cons_mem_piFinset_cons",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {x_zero : α 0} {x_tail : (i : Fin n) → α i.succ} {s_zero : Finset (α 0)} {s_tail : (i : Fin n) → Finset (α i.succ)} : Fin.cons x_zero x_tail ∈ Fintype.piFinset (Fin.cons s_zero s_tail) ↔ x_zero ∈ s_zero ∧ x_tail ∈ Fintype.piFinset s_tail",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    },
    {
      "name": "Fin.mem_piFinset_iff_zero_tail",
      "type": " {n : ℕ} {α : Fin (n + 1) → Type u_1} {f : (i : Fin (n + 1)) → α i} {s : (i : Fin (n + 1)) → Finset (α i)} : f ∈ Fintype.piFinset s ↔ f 0 ∈ s 0 ∧ Fin.tail f ∈ Fintype.piFinset (Fin.tail s)",
      "module": "Mathlib.Data.Fin.Tuple.Finset"
    }
  ]
}
